import{_ as t,o as a,c as o,a0 as r}from"./chunks/framework.Bmhw_dvp.js";const u=JSON.parse('{"title":"Dashboard Deployment","description":"","frontmatter":{},"headers":[],"relativePath":"guide/dashboard.md","filePath":"guide/dashboard.md"}'),i={name:"guide/dashboard.md"};function l(s,e,n,d,c,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="dashboard-deployment" tabindex="-1">Dashboard Deployment <a class="header-anchor" href="#dashboard-deployment" aria-label="Permalink to &quot;Dashboard Deployment&quot;">​</a></h1><p>Deploy Cloud Mail directly from the Cloudflare Dashboard by importing your GitHub repository.</p><h2 id="step-1-fork-the-repository" tabindex="-1">Step 1: Fork the Repository <a class="header-anchor" href="#step-1-fork-the-repository" aria-label="Permalink to &quot;Step 1: Fork the Repository&quot;">​</a></h2><ol><li>Go to <a href="https://github.com/maillab/cloud-mail" target="_blank" rel="noreferrer">github.com/maillab/cloud-mail</a></li><li>Click <strong>Fork</strong> to copy it to your GitHub account</li></ol><h2 id="step-2-create-a-new-worker" tabindex="-1">Step 2: Create a New Worker <a class="header-anchor" href="#step-2-create-a-new-worker" aria-label="Permalink to &quot;Step 2: Create a New Worker&quot;">​</a></h2><ol><li>Open the <a href="https://dash.cloudflare.com" target="_blank" rel="noreferrer">Cloudflare Dashboard</a></li><li>Navigate to <strong>Workers &amp; Pages</strong></li><li>Click <strong>Create Application</strong> → <strong>Worker</strong></li><li>Choose <strong>Import from GitHub</strong></li></ol><h2 id="step-3-configure-the-worker" tabindex="-1">Step 3: Configure the Worker <a class="header-anchor" href="#step-3-configure-the-worker" aria-label="Permalink to &quot;Step 3: Configure the Worker&quot;">​</a></h2><ol><li>Select your forked repository</li><li>Set the directory to <strong><code>mail-worker</code></strong></li><li>Click <strong>Deploy</strong></li></ol><h2 id="step-4-set-environment-variables" tabindex="-1">Step 4: Set Environment Variables <a class="header-anchor" href="#step-4-set-environment-variables" aria-label="Permalink to &quot;Step 4: Set Environment Variables&quot;">​</a></h2><p>Go to your Worker&#39;s <strong>Settings → Variables</strong> and add:</p><table tabindex="0"><thead><tr><th>Variable</th><th>Required</th><th>Description</th><th>Example</th></tr></thead><tbody><tr><td><code>domain</code></td><td>✅</td><td>Email domain(s) as JSON array</td><td><code>[&quot;example.com&quot;]</code></td></tr><tr><td><code>admin</code></td><td>✅</td><td>Admin email address</td><td><code>admin@example.com</code></td></tr><tr><td><code>jwt_secret</code></td><td>✅</td><td>Random string for JWT tokens</td><td><code>my-secret-key-123</code></td></tr></tbody></table><blockquote><p><strong>Note:</strong> <code>jwt_secret</code> must not contain special characters.</p></blockquote><h2 id="step-5-bind-databases" tabindex="-1">Step 5: Bind Databases <a class="header-anchor" href="#step-5-bind-databases" aria-label="Permalink to &quot;Step 5: Bind Databases&quot;">​</a></h2><h3 id="create-kv-namespace" tabindex="-1">Create KV Namespace <a class="header-anchor" href="#create-kv-namespace" aria-label="Permalink to &quot;Create KV Namespace&quot;">​</a></h3><ol><li>Go to <strong>Workers &amp; Pages → KV</strong></li><li>Click <strong>Create Namespace</strong></li><li>Name it (e.g., <code>cloud-mail-kv</code>)</li><li>Go back to your Worker → <strong>Settings → Variables → KV Namespace Bindings</strong></li><li>Add binding with <strong>Variable name: <code>kv</code></strong></li></ol><h3 id="create-d1-database" tabindex="-1">Create D1 Database <a class="header-anchor" href="#create-d1-database" aria-label="Permalink to &quot;Create D1 Database&quot;">​</a></h3><ol><li>Go to <strong>Workers &amp; Pages → D1</strong></li><li>Click <strong>Create Database</strong></li><li>Name it (e.g., <code>cloud-mail-db</code>)</li><li>Go back to your Worker → <strong>Settings → Variables → D1 Database Bindings</strong></li><li>Add binding with <strong>Variable name: <code>db</code></strong></li></ol><h2 id="step-6-configure-email-routing-receive-emails" tabindex="-1">Step 6: Configure Email Routing (Receive Emails) <a class="header-anchor" href="#step-6-configure-email-routing-receive-emails" aria-label="Permalink to &quot;Step 6: Configure Email Routing (Receive Emails)&quot;">​</a></h2><ol><li>Go to <strong>Email → Email Routing</strong> in Cloudflare Dashboard</li><li>Enable Email Routing for your domain</li><li>Go to <strong>Email → Email Routing → Routes</strong></li><li>Create a catch-all route pointing to your Worker</li><li>Select your Worker as the destination</li></ol><h2 id="step-7-initialize-the-database" tabindex="-1">Step 7: Initialize the Database <a class="header-anchor" href="#step-7-initialize-the-database" aria-label="Permalink to &quot;Step 7: Initialize the Database&quot;">​</a></h2><ol><li>Open your Worker URL in a browser:<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://&lt;your-worker&gt;.workers.dev/api/init/&lt;your-jwt_secret&gt;</span></span></code></pre></div></li><li>You should see a success message</li></ol><h2 id="step-8-log-in" tabindex="-1">Step 8: Log In <a class="header-anchor" href="#step-8-log-in" aria-label="Permalink to &quot;Step 8: Log In&quot;">​</a></h2><ol><li>Navigate to your Worker URL</li><li>Click <strong>Register</strong> and create the admin account</li><li>Sign in with your admin credentials</li></ol><p>🎉 <strong>Done!</strong> Your Cloud Mail service is now live.</p><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li>Add more users and domains</li><li>Configure custom domain for the Worker</li><li>Set up R2 for attachment storage</li></ul>',26)])])}const g=t(i,[["render",l]]);export{u as __pageData,g as default};
